import bisect
import collections

class TimeMap:
    def __init__(self):
        self.store = collections.defaultdict(list)

    def set(self, key: str, value: str, timestamp: int) -> None:
        self.store[key].append((timestamp, value))

    def get(self, key: str, timestamp: int) -> str:
        if key not in self.store:
            return ""
        arr = self.store[key]
        idx = bisect.bisect_right(arr, (timestamp, chr(127))) - 1
        if idx >= 0:
            return arr[idx][1]
        return ""

class TimeMap {
    unordered_map<string, vector<pair<int, string>>> store;
public:
    TimeMap() {}

    void set(string key, string value, int timestamp) {
        store[key].push_back({timestamp, value});
    }

    string get(string key, int timestamp) {
        if (!store.count(key)) return "";
        const auto& arr = store[key];
        int low = 0, high = arr.size() - 1;
        int idx = -1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (arr[mid].first <= timestamp) {
                idx = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return idx == -1 ? "" : arr[idx].second;
    }
};

import java.util.*;

class TimeMap {
    static class Entry {
        int timestamp;
        String val;
        Entry(int t, String v) { timestamp = t; val = v; }
    }
    private Map<String, List<Entry>> store;

    public TimeMap() {
        store = new HashMap<>();
    }

    public void set(String key, String value, int timestamp) {
        store.computeIfAbsent(key, k -> new ArrayList<>()).add(new Entry(timestamp, value));
    }

    public String get(String key, int timestamp) {
        if (!store.containsKey(key)) return "";
        List<Entry> list = store.get(key);
        int low = 0, high = list.size() - 1;
        int idx = -1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (list.get(mid).timestamp <= timestamp) {
                idx = mid;
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return idx == -1 ? "" : list.get(idx).val;
    }
}

var TimeMap = function() {
    this.store = new Map();
};

/** 
 * @param {string} key 
 * @param {string} value 
 * @param {number} timestamp
 * @return {void}
 */
TimeMap.prototype.set = function(key, value, timestamp) {
    if (!this.store.has(key)) this.store.set(key, []);
    this.store.get(key).push([timestamp, value]);
};

/** 
 * @param {string} key 
 * @param {number} timestamp
 * @return {string}
 */
TimeMap.prototype.get = function(key, timestamp) {
    if (!this.store.has(key)) return '';
    const arr = this.store.get(key);
    let low = 0, high = arr.length - 1;
    let idx = -1;
    while (low <= high) {
        const mid = (low + high) >> 1;
        if (arr[mid][0] <= timestamp) {
            idx = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    return idx === -1 ? '' : arr[idx][1];
};
